function getServiceById(id) {
  return MASTER_SERVICES.find(s => s.id === parseInt(id));
}

function getServicesByCategory(catId) {
  if (!catId || catId === 'all') return MASTER_SERVICES;
  return MASTER_SERVICES.filter(s => s.category === catId);
}
